import ReactECharts from 'echarts-for-react';
import React, { useMemo, useState, useRef } from 'react';
import EquivalenceChart from './EquivalenceChart';

const GalleryChart = ({
  data = [],
  type = ['scatter', 'box'],
  groupkey = ['partid', 'step', 'y1item'],
  lkey = ['equip'], // 다중 컬럼 설정
  xkey = 'tkout_time',
  ykey = 'value',
  cols = 3,
}) => {
  const [expandedCat, setExpandedCat] = useState(null);
  const expandedChartRef = useRef(null);
  const [legendPos, setLegendPos] = useState('bottom');
  const [selectedCols, setSelectedCols] = useState(['lot_id', 'wafer_id', 'value', 'tkout_time']);
  const [isColModalOpen, setIsColModalOpen] = useState(false);

  // 🎨 색상 팔레트
  const chartColors = useMemo(() => {
    const basePalette = [
      '#5470c6',
      '#91cc75',
      '#fac858',
      '#ee6666',
      '#73c0de',
      '#3ba272',
      '#fc8452',
      '#9a60b4',
      '#ea7ccc',
    ];
    let extended = [...basePalette];
    while (extended.length < 50) {
      extended.push(basePalette[extended.length % basePalette.length] + 'AA');
    }
    return extended;
  }, []);

  const allColumns = useMemo(() => (data.length > 0 ? Object.keys(data[0]) : []), [data]);

  // 공통: lkey 리스트를 기반으로 하나의 고유한 문자열 키를 생성하는 함수
  const getLName = (item) => lkey.map((k) => item[k] ?? 'N/A').join(' / ');

  const handleColToggle = (col) => {
    setSelectedCols((prev) =>
      prev.includes(col) ? prev.filter((c) => c !== col) : [...prev, col],
    );
  };

  const grouped = useMemo(() => {
    return data.reduce((acc, curr) => {
      const catName = groupkey.map((key) => curr[key]).join(' / ');
      if (!acc[catName]) acc[catName] = [];
      acc[catName].push(curr);
      return acc;
    }, {});
  }, [data, groupkey]);

  const chartTypes = Array.isArray(type) ? type : [type];
  const gridCols = chartTypes.length > 1 ? chartTypes.length : cols;

  // --- 차트 제어 함수들 ---
  const handleZoomInMode = () => {
    const instance = expandedChartRef.current.getEchartsInstance();
    instance.dispatchAction({
      type: 'takeGlobalCursor',
      key: 'dataZoomSelect',
      dataZoomSelectActive: true,
    });
  };

  const handlePanMode = () => {
    const instance = expandedChartRef.current.getEchartsInstance();
    instance.dispatchAction({
      type: 'takeGlobalCursor',
      key: 'dataZoomSelect',
      dataZoomSelectActive: false, // 영역 선택을 끄면 기본 드래그(Pan)가 작동함
    });
  };

  const handleRestore = () => {
    const instance = expandedChartRef.current.getEchartsInstance();
    instance.dispatchAction({
      type: 'restore', // 차트 초기 상태로 복구
    });
  };

  const getOption = (cat, items, currentType, isExpanded) => {
    // 🔍 핵심: 모든 lkey 컬럼을 조합하여 범례 리스트 생성
    const legends = [...new Set(items.map((i) => getLName(i)))].sort();

    const currentPos = isExpanded ? legendPos : 'bottom';
    const isVertical = currentPos === 'left' || currentPos === 'right';

    let xAxis = { type: 'category' };
    let yAxis = { type: 'value', scale: true, splitLine: { lineStyle: { type: 'dashed' } } };
    let series = [];

    // 1. scatter-priority (Legend별(equip,...) 구역 나눔)
    if (currentType === 'scatter-priority') {
      let sortedItems = [...items].sort((a, b) => {
        const aL = getLName(a);
        const bL = getLName(b);
        if (aL !== bL) return aL.localeCompare(bL);
        return new Date(a[xkey]) - new Date(b[xkey]);
      });

      const compositeLabels = sortedItems.map((i) => `${getLName(i)}\n${i[xkey]}`);

      xAxis = [
        {
          type: 'category',
          data: compositeLabels,
          axisLabel: {
            show: isExpanded,
            rotate: 45,
            fontSize: 10,
            formatter: (val) => val.split('\n')[1],
          },
          splitLine: {
            show: true,
            interval: (idx, val) =>
              idx !== 0 && val.split('\n')[0] !== compositeLabels[idx - 1].split('\n')[0],
            lineStyle: { type: 'solid', color: '#333', width: 2 },
          },
        },
        {
          type: 'category',
          position: 'bottom',
          offset: 45,
          data: legends,
          axisPointer: { type: 'none' },
          axisTick: { length: 50, lineStyle: { color: '#ccc', width: 2 } },
          axisLabel: { fontWeight: 'bold', fontSize: 11, color: '#333', interval: 0 },
        },
      ];

      series = legends.map((leg, idx) => ({
        name: leg,
        type: 'scatter',
        xAxisIndex: 0,
        itemStyle: { color: chartColors[idx % chartColors.length] },
        data: sortedItems
          .filter((i) => getLName(i) === leg)
          .map((i) => ({
            value: [`${getLName(i)}\n${i[xkey]}`, i[ykey]],
            raw: i,
          })),
        symbolSize: isExpanded ? 8 : 5,
      }));
    }

    // 2. ncdf / ecdf
    else if (['ncdf', 'ecdf', 'ecdf-normal', 'ecdf-overlay'].includes(currentType)) {
      const isNCDF = currentType === 'ncdf';
      xAxis = { type: 'value', scale: !isNCDF };
      yAxis = { type: 'value', scale: isNCDF };

      series = legends.map((leg, idx) => {
        const fData = items.filter((i) => getLName(i) === leg).sort((a, b) => a[ykey] - b[ykey]);
        return {
          name: leg,
          type: 'line',
          step: currentType.includes('normal') ? false : 'end',
          itemStyle: { color: chartColors[idx % chartColors.length] },
          data: fData.map((i, index) => {
            const prob = (index + 0.5) / fData.length;
            return { value: isNCDF ? [prob, i[ykey]] : [i[ykey], prob], raw: i };
          }),
        };
      });
    }

    // 3. scatter
    else if (currentType === 'scatter') {
      xAxis = {
        type: 'time',
        axisLabel: {
          show: isExpanded,
          formatter: items.map((i) => {
            const date = new Date(i[xkey]);
            return `${date.getMonth() + 1}/${date.getDate()} ${date.getHours()}:${date.getMinutes()}`;
          }),
        },
        splitLine: { show: true, lineStyle: { type: 'dashed' } },
      };

      series = legends.map((leg, idx) => ({
        name: leg,
        type: currentType,
        itemStyle: { color: chartColors[idx % chartColors.length] },
        data: items
          .filter((i) => getLName(i) === leg)
          .map((i) => ({
            value: [new Date(i[xkey]), i[ykey]],
            raw: i,
          })),
        symbolSize: isExpanded ? 8 : 4,
      }));
    }

    // 4. scatter-data & line
    else if (currentType === 'scatter-data') {
      const sortedItems = [...items].sort((a, b) => new Date(a[xkey]) - new Date(b[xkey]));
      const xAxisData = [...new Set(sortedItems.map((i) => i[xkey]))];
      xAxis = {
        type: 'category',
        data: xAxisData,
        axisLabel: { show: isExpanded, rotate: 30 },
        splitLine: { show: true, lineStyle: { color: '#eee' } },
      };

      series = legends.map((leg, idx) => ({
        name: leg,
        type: 'scatter',
        itemStyle: { color: chartColors[idx % chartColors.length] },
        data: items
          .filter((i) => getLName(i) === leg)
          .map((i) => ({
            value: [i[xkey], i[ykey]],
            raw: i,
          })),
        smooth: currentType === 'line',
        symbolSize: isExpanded ? 8 : 4,
        connectNulls: true,
      }));
    }

    // 4. Box Plot
    else if (currentType === 'box') {
      xAxis = { type: 'category', data: [''] };
      series = legends.map((leg, idx) => {
        const values = items
          .filter((i) => getLName(i) === leg)
          .map((i) => i[ykey])
          .sort((a, b) => a - b);
        const color = chartColors[idx % chartColors.length];
        const boxData =
          values.length === 0
            ? [0, 0, 0, 0, 0]
            : [
                values[0],
                values[Math.floor(values.length * 0.25)],
                values[Math.floor(values.length * 0.5)],
                values[Math.floor(values.length * 0.75)],
                values[values.length - 1],
              ];
        return {
          name: leg,
          type: 'boxplot',
          data: [boxData],
          itemStyle: { borderColor: color, borderWidth: 2, color: color + '33' },
        };
      });
    }

    return {
      title: {
        text: isExpanded ? cat : `${cat} (${currentType.toUpperCase()})`,
        left: 'center',
        textStyle: { fontSize: 12 },
      },
      tooltip: {
        trigger: 'item',
        formatter: (params) => {
          const p = Array.isArray(params) ? params[0] : params;
          if (!p.data) return '';
          let res = `<div style="padding:5px;"><b>${p.seriesName}</b><br/>`;
          if (p.seriesType === 'boxplot') {
            const val = p.data.value || p.data;
            const [min, q1, med, q3, max] = val.length >= 6 ? val.slice(1) : val;
            res += `Max: ${max}<br/>Q3: ${q3}<br/>Median: ${med}<br/>Q1: ${q1}<br/>Min: ${min}`;
          } else {
            const raw = p.data.raw || {};
            selectedCols.forEach((col) => {
              res += `${col}: ${raw[col] ?? '-'}<br/>`;
            });
          }
          return res + `</div>`;
        },
      },
      legend: {
        show: isExpanded,
        type: 'scroll',
        orient: isVertical ? 'vertical' : 'horizontal',
        bottom: 5,
      },
      grid: { top: '15%', bottom: '15%', containLabel: true },
      dataZoom: isExpanded
        ? [
            { type: 'inside', moveOnMouseMove: true }, // 마우스 휠 줌 및 이동
            { type: 'slider', show: true }, // 하단 슬라이더 추가
          ]
        : [],
      xAxis,
      yAxis,
      series,
    };
  };

  return (
    <div style={{ position: 'relative' }}>
      {isColModalOpen && (
        <div style={modalOverlayStyle}>
          <div style={modalContentStyle}>
            <h4>Columns 설정</h4>
            <div style={columnGridStyle}>
              {allColumns.map((col) => (
                <label key={col} style={{ display: 'flex', gap: '5px', fontSize: '12px' }}>
                  <input
                    type="checkbox"
                    checked={selectedCols.includes(col)}
                    onChange={() => handleColToggle(col)}
                  />
                  {col}
                </label>
              ))}
            </div>
            <button onClick={() => setIsColModalOpen(false)} style={modalCloseBtnStyle}>
              닫기
            </button>
          </div>
        </div>
      )}

      {expandedCat && (
        <div style={expandedOverlayStyle}>
          <div style={toolbarStyle}>
            <div>
              <b style={{ marginRight: '20px' }}>{expandedCat.cat}</b>
              {expandedCat.type !== 'equivalence' && (
                <div style={{ display: 'inline-flex', gap: '5px' }}>
                  <button onClick={handleZoomInMode} style={controlBtnStyle}>
                    🔍 영역확대
                  </button>
                  <button onClick={handlePanMode} style={controlBtnStyle}>
                    ✋ 이동
                  </button>
                  <button onClick={handleRestore} style={controlBtnStyle}>
                    🔄 초기화
                  </button>
                </div>
              )}
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              <button onClick={() => setIsColModalOpen(true)} style={colSettingBtnStyle}>
                ⚙ Columns
              </button>
              <button onClick={() => setExpandedCat(null)} style={closeBtnStyle}>
                닫기
              </button>
            </div>
          </div>

          <div style={{ flex: 1 }}>
            {expandedCat.type === 'equivalence' ? (
              <EquivalenceChart data={grouped[expandedCat.cat]} title={expandedCat.cat} />
            ) : (
              <ReactECharts
                ref={expandedChartRef}
                option={getOption(
                  expandedCat.cat,
                  grouped[expandedCat.cat],
                  expandedCat.type,
                  true,
                )}
                style={{ height: '100%' }}
                notMerge={true}
              />
            )}
          </div>
        </div>
      )}

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: `repeat(${gridCols}, 1fr)`,
          gap: '10px',
          opacity: expandedCat ? 0.1 : 1,
        }}
      >
        {Object.entries(grouped).map(([cat, items]) =>
          chartTypes.map((t) => (
            <div
              key={`${cat}-${t}`}
              onDoubleClick={() => setExpandedCat({ cat, type: t })}
              style={cardStyle}
            >
              {t === 'equivalence' ? (
                <EquivalenceChart data={items} title={cat} />
              ) : (
                <ReactECharts
                  option={getOption(cat, items, t, false)}
                  style={{ height: '100%' }}
                  notMerge={true}
                />
              )}
            </div>
          )),
        )}
      </div>
    </div>
  );
};

// --- 추가된 스타일 ---
const controlBtnStyle = {
  padding: '4px 8px',
  fontSize: '12px',
  cursor: 'pointer',
  backgroundColor: '#f8f9fa',
  border: '1px solid #ccc',
  borderRadius: '4px',
};

// --- Styles (최소화) ---
const cardStyle = {
  border: '1px solid #eee',
  borderRadius: '8px',
  height: '280px',
  backgroundColor: '#fff',
};
const modalOverlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'rgba(0,0,0,0.5)',
  zIndex: 2000,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
};
const modalContentStyle = {
  backgroundColor: '#fff',
  padding: '20px',
  borderRadius: '12px',
  width: '300px',
};
const columnGridStyle = {
  display: 'grid',
  gridTemplateColumns: '1fr 1fr',
  gap: '5px',
  maxHeight: '200px',
  overflowY: 'auto',
  margin: '10px 0',
};
const modalCloseBtnStyle = {
  width: '100%',
  padding: '8px',
  backgroundColor: '#007bff',
  color: '#fff',
  border: 'none',
};
const expandedOverlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  zIndex: 1000,
  backgroundColor: '#fff',
  padding: '20px',
  display: 'flex',
  flexDirection: 'column',
};
const toolbarStyle = { display: 'flex', justifyContent: 'space-between', marginBottom: '10px' };
const closeBtnStyle = {
  padding: '4px 12px',
  backgroundColor: '#444',
  color: '#fff',
  border: 'none',
};
const colSettingBtnStyle = {
  padding: '4px 8px',
  border: '1px solid #007bff',
  color: '#007bff',
  backgroundColor: '#fff',
};

export default GalleryChart;
