import React, { useRef, useEffect, useState, useMemo } from 'react';

const GradientMap = ({
  params,
  data = [], // 기본값 설정
  type = 'shot',
  xkey = 'x',
  ykey = 'y',
  cdkey = 'cdvalue', // 데이터 구조에 맞게 조정 가능
  pointStyle = 'circle',
  pointSize = 5,
  colors = [],
}) => {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const [dimensions, setDimensions] = useState(0);
  const [hoveredPoint, setHoveredPoint] = useState(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const PARULA_COLORS = [
    '#352a87',
    '#0f5cdd',
    '#1481d6',
    '#06a4ca',
    '#2eb7a4',
    '#87bf77',
    '#d1bb59',
    '#fec832',
    '#f9fb0e',
  ];

  // 1. Params 기반으로 Shot의 논리적 크기 동적 계산
  const SHOT_W = useMemo(() => {
    if (!params?.dieSizeX) return 27000; // 기본값 방어 코드
    return type === 'shot' ? (params.dieSizeX + (params.scribeSize || 0)) * 3 : params.dieSizeX;
  }, [params.dieSizeX, params.scribeSize, params.type]);

  const SHOT_H = useMemo(() => {
    if (!params?.dieSizeY) return 27000; // 기본값 방어 코드
    return type === 'shot' ? (params.dieSizeY + (params.scribeSize || 0)) * 3 : params.dieSizeY;
  }, [params.dieSizeY, params.scribeSize, params.type]);

  // HEX를 RGB 객체로 변환 (에러 방지 강화)
  const hexToRgb = (hex) => {
    if (!hex || typeof hex !== 'string') return { r: 0, g: 0, b: 0 };
    const cleanHex = hex.startsWith('#') ? hex.slice(1) : hex;
    const r = parseInt(cleanHex.slice(0, 2), 16) || 0;
    const g = parseInt(cleanHex.slice(2, 4), 16) || 0;
    const b = parseInt(cleanHex.slice(4, 6), 16) || 0;
    return { r, g, b };
  };

  // 1. rgbPalette 생성 시 기본 팔레트 보장
  const rgbPalette = useMemo(() => {
    const target = colors && colors.length > 0 ? colors : PARULA_COLORS;
    // hexToRgb 결과가 올바른지 확인하며 맵핑
    return target.map((hex) => hexToRgb(hex));
  }, [colors]);

  const interpolateColor = (rgbList, factor) => {
    // [방어 코드] 리스트가 비어있으면 검정색 기본값 반환
    if (!rgbList || rgbList.length === 0) return { r: 0, g: 0, b: 0 };

    const f = Math.max(0, Math.min(1, factor));
    const idx = f * (rgbList.length - 1);
    const i = Math.floor(idx);
    const nextI = Math.min(i + 1, rgbList.length - 1);
    const remainder = idx - i;

    // [방어 코드] 인덱스로 가져온 값이 undefined일 경우를 대비해 기본값 설정
    const c1 = rgbList[i] || { r: 0, g: 0, b: 0 };
    const nextColor = rgbList[nextI];

    // 만약 마지막 인덱스라면 c1과 동일하게 처리
    const c2 = nextColor || c1;

    return {
      r: Math.round(c1.r + (c2.r - c1.r) * remainder),
      g: Math.round(c1.g + (c2.g - c1.g) * remainder),
      b: Math.round(c1.b + (c2.b - c1.b) * remainder),
    };
  };

  // --- 추가된 부분: 데이터 기반 min, max 계산 ---
  const { minV, maxV } = useMemo(() => {
    if (!data || data.length === 0) return { minV: 0, maxV: 100 };

    // 데이터에서 cdkey에 해당하는 값들만 추출 (숫자가 아닌 경우 대비 0 처리)
    const values = data.map((d) => Number(d[cdkey]) || 0);
    return {
      minV: Math.min(...values),
      maxV: Math.max(...values),
    };
  }, [data, cdkey]);

  const getColors = (value) => {
    // 동적 정규화: (현재값 - 최소값) / (최대값 - 최소값)
    const range = maxV - minV || 1; // 모든 값이 같을 경우 분모가 0이 되는 것 방지
    const normalized = (value - minV) / range;

    const currentPalette = rgbPalette && rgbPalette.length > 0 ? rgbPalette : [];
    const { r, g, b } = interpolateColor(currentPalette, normalized);

    return {
      fill: `rgb(${r}, ${g}, ${b})`,
      stroke: `rgb(${Math.max(0, r - 30)}, ${Math.max(0, g - 30)}, ${Math.max(0, b - 30)})`,
    };
  };

  // 밝기 조절 함수 (테두리용)
  const getStrokeColor = (fillRGB) => {
    // rgb(r, g, b) 문자열에서 숫자 추출
    const rgb = fillRGB.match(/\d+/g);
    if (!rgb) return '#333';
    const darken = 0.8;
    return `rgb(${Math.floor(rgb[0] * darken)}, ${Math.floor(rgb[1] * darken)}, ${Math.floor(rgb[2] * darken)})`;
  };

  const drawShape = (ctx, x, y, size, fill, type, isHovered = false) => {
    ctx.beginPath();
    ctx.fillStyle = fill;
    ctx.strokeStyle = isHovered ? '#000' : getStrokeColor(fill);
    ctx.lineWidth = isHovered ? 2 : 0.5;

    switch (type) {
      case 'rect':
        ctx.rect(x - size / 2, y - size / 2, size, size);
        break;
      case 'circle':
        ctx.arc(x, y, size / 2, 0, Math.PI * 2);
        break;
      case 'diamond':
        ctx.moveTo(x, y - size / 2);
        ctx.lineTo(x + size / 2, y);
        ctx.lineTo(x, y + size / 2);
        ctx.lineTo(x - size / 2, y);
        break;
      case 'tri-up':
        ctx.moveTo(x, y - size / 2);
        ctx.lineTo(x + size / 2, y + size / 2);
        ctx.lineTo(x - size / 2, y + size / 2);
        break;
      case 'tri-down':
        ctx.moveTo(x - size / 2, y - size / 2);
        ctx.lineTo(x + size / 2, y - size / 2);
        ctx.lineTo(x, y + size / 2);
        break;
      default:
        ctx.arc(x, y, size / 2, 0, Math.PI * 2);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  };

  useEffect(() => {
    const observeTarget = containerRef.current;
    const resizeObserver = new ResizeObserver((entries) => {
      for (let entry of entries) {
        const { width, height } = entry.contentRect;
        setDimensions(Math.min(width, height));
      }
    });
    if (observeTarget) resizeObserver.observe(observeTarget);
    return () => resizeObserver.disconnect();
  }, []);

  useEffect(() => {
    if (dimensions === 0 || !data) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    const padding = dimensions * 0.01;
    const safeSize = dimensions - padding * 2;

    // 가로/세로 중 더 큰 값을 기준으로 스케일 결정 (Aspect Ratio 유지)
    const maxBound = Math.max(SHOT_W, SHOT_H);
    const scale = safeSize / maxBound;

    // 실제 Shot 영역이 차지하는 픽셀 크기
    const viewW = SHOT_W * scale;
    const viewH = SHOT_H * scale;

    // 중앙 정렬을 위한 오프셋
    const offsetX = padding + (safeSize - viewW) / 2;
    const offsetY = padding + (safeSize - viewH) / 2;

    ctx.clearRect(0, 0, dimensions, dimensions);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, dimensions, dimensions);

    // 가이드 테두리
    ctx.strokeStyle = '#747171';
    ctx.lineWidth = 1;
    ctx.strokeRect(offsetX, offsetY, viewW, viewH);

    // hovered 용
    let fillColor = '#fff';
    let x = 0;
    let y = 0;
    let tipDraw = false;
    data.forEach((point) => {
      const { fill } = getColors(point[cdkey] || 0);
      const drawX = offsetX + point[xkey] * scale;
      const drawY = offsetY + point[ykey] * scale; // Y축 반전이 필요할 경우 대비
      if (hoveredPoint?.id === point.id) {
        fillColor = fill;
        x = drawX;
        y = drawY;
        tipDraw = true;
      }
      drawShape(ctx, drawX, drawY, pointSize, fill, pointStyle);
    });
    if (tipDraw) drawShape(ctx, x, y, pointSize + 4, fillColor, pointStyle, tipDraw);
  }, [dimensions, data, hoveredPoint, colors, pointStyle, pointSize]);

  const handleMouseMove = (e) => {
    if (!canvasRef.current || dimensions === 0) return;
    const rect = canvasRef.current.getBoundingClientRect();

    // 1. 마우스의 캔버스 내 상대 좌표
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    // 2. 그리기 로직과 동일한 스케일 및 오프셋 계산
    const padding = dimensions * 0.01;
    const safeSize = dimensions - padding * 2;
    const maxBound = Math.max(SHOT_W, SHOT_H);
    const scale = safeSize / maxBound;

    const viewW = SHOT_W * scale;
    const viewH = SHOT_H * scale;

    const offsetX = padding + (safeSize - viewW) / 2;
    const offsetY = padding + (safeSize - viewH) / 2;

    // 3. 근접 포인트 찾기 (그려진 위치 drawX, drawY와 동일하게 계산)
    const found = data.find((p) => {
      const px = offsetX + p[xkey] * scale;
      const py = offsetY + p[ykey] * scale; // drawY와 동일하게 수정 (반전 제거)

      // 마우스 좌표와 포인트 좌표 사이의 거리 계산 (반경 8px 이내)
      const distance = Math.sqrt((px - mx) ** 2 + (py - my) ** 2);
      return distance < pointSize + 3; // 포인트 크기에 여유분(+3) 추가
    });

    if (found) {
      setHoveredPoint(found);
      setTooltipPos({ x: e.clientX + 15, y: e.clientY + 15 });
    } else {
      setHoveredPoint(null);
    }
  };
  return (
    <div
      ref={containerRef}
      style={{
        width: '100%',
        height: '100%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: '#f5f5f5',
      }}
    >
      <div style={{ position: 'relative', width: dimensions, height: dimensions }}>
        <canvas
          ref={canvasRef}
          className="gradient-canvas-map"
          width={dimensions}
          height={dimensions}
          onMouseMove={handleMouseMove}
          onMouseLeave={() => setHoveredPoint(null)}
          style={{ display: 'block', backgroundColor: '#fff', cursor: 'pointer' }}
        />
        {hoveredPoint && (
          <div
            style={{
              position: 'fixed',
              left: tooltipPos.x,
              top: tooltipPos.y,
              backgroundColor: 'rgba(15, 23, 42, 0.9)',
              backdropFilter: 'blur(6px)',
              color: '#fff',
              padding: '12px',
              borderRadius: '8px',
              fontSize: '12px',
              pointerEvents: 'none',
              zIndex: 9999,
              border: '1px solid rgba(255,255,255,0.1)',
              boxShadow: '0 10px 15px -3px rgba(0,0,0,0.5)',
            }}
          >
            <div style={tooltipHeaderStyle}>{type.toUpperCase()} DATA</div>
            <div style={tooltipGridStyle}>
              <span style={labelStyle}>ID:</span> <span style={valueStyle}>{hoveredPoint.id}</span>
              <span style={labelStyle}>X/Y:</span>{' '}
              <span style={valueStyle}>
                {hoveredPoint[xkey].toFixed(0)}/{hoveredPoint[ykey].toFixed(0)}
              </span>
              <span style={labelStyle}>Value:</span>{' '}
              <span style={{ ...valueStyle, color: '#60a5fa' }}>
                {hoveredPoint[cdkey].toFixed(2)}
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const tooltipHeaderStyle = {
  color: '#38bdf8',
  fontSize: '10px',
  fontWeight: '800',
  marginBottom: '6px',
  letterSpacing: '0.5px',
};
const tooltipGridStyle = { display: 'grid', gridTemplateColumns: 'auto auto', gap: '2px 10px' };
const labelStyle = { color: '#94a3b8', fontWeight: '500' };
const valueStyle = { fontWeight: 'bold', fontFamily: 'monospace' };
export default GradientMap;
