import React, { useState } from 'react';
import SearchEquivalence from './Search-Equivalence';
import ChartPack from './ChartPack';
import { generateDatas } from '../utils/DataGenerator';

const LayoutEquivalence = ({ moduleId = 0 }) => {
  const [data, setData] = useState([]);
  const [analysisType, setAnalysisType] = useState('Equivalence Analysis');
  const [chartType, setChartType] = useState([
    'scatter',
    'scatter-data',
    'scatter-priority',
    'equivalence',
  ]);
  const [activeTab, setActiveTab] = useState('search');
  const [gridCols, setGridCols] = useState(4);

  // 1. 열려있는 탭 목록과 활성화된 탭 ID 관리
  const [openTabs, setOpenTabs] = useState([]);

  const handleRun = (selectedParams) => {
    const newData = generateDatas(selectedParams);
    setAnalysisType(selectedParams.analysisType);
    setChartType(selectedParams.chartType);
    setGridCols(selectedParams.chartCols);
    setData(newData);

    // 1. 이미 열려있는 동일 타입의 탭 확인
    const type = 'ChartPack';
    const existingTabs = openTabs.filter((tab) => tab.originalType === type);
    const isAlreadyOpen = existingTabs.length > 0;

    // 4. 새 탭을 위한 ID와 Label 생성
    let newInstanceId = type;
    let newLabel = selectedParams.title;

    if (isAlreadyOpen) {
      newInstanceId = `${type}_${Date.now()}`; // 고유 ID를 위해 타임스탬프 활용 권장
    }

    // 5. 탭 추가 및 활성화
    const newTab = {
      id: newInstanceId,
      label: newLabel,
      originalType: type,
    };

    setOpenTabs([...openTabs, newTab]);
    setActiveTab(newInstanceId);
  };

  // 3. 탭 닫기 핸들러
  const closeTab = (e, id) => {
    e.stopPropagation(); // 탭 전환 이벤트 전파 방지
    const newTabs = openTabs.filter((tab) => tab.id !== id);
    setOpenTabs(newTabs);

    // 닫은 탭이 활성 탭이었다면 마지막 남은 탭으로 이동
    if (activeTab === id && newTabs.length > 0) {
      setActiveTab(newTabs[newTabs.length - 1].id);
    } else {
      setActiveTab('search');
    }
  };

  return (
    <div
      style={{
        display: 'flex', // Flexbox 적용
        flexDirection: 'column', // 세로 방향 배치
        height: 'calc(100vh - 102px)', // 화면 전체 높이 고정 (브라우저 스크롤 방지)
        padding: '0 15px',
        fontFamily: 'Arial',
        boxSizing: 'border-box',
        overflow: 'hidden', // 부모의 넘침 방지
      }}
    >
      {/* 4. 다이나믹 탭 바 영역 */}
      <div
        style={{
          display: 'flex',
          backgroundColor: '#fff',
          zIndex: 101,
          marginTop: '3px',
          borderBottom: '2px solid #ddd',
          flexShrink: 0, // 탭 영역이 줄어들지 않도록 설정
        }}
      >
        <button onClick={() => setActiveTab('search')} style={tabStyle(activeTab === 'search')}>
          🔍 Search
        </button>
        {openTabs.map((tab, idx) => (
          <div
            key={tab.id}
            className={`tab-item ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
            style={tabStyle(activeTab === tab.id)}
          >
            <span>{`${tab.label} (${idx + 1})`}</span>
            <button className="close-btn" onClick={(e) => closeTab(e, tab.id)}>
              ×
            </button>
          </div>
        ))}
      </div>

      {/* 5. 컨텐츠 렌더링 영역 */}
      <div
        style={{
          flex: 1, // 남은 화면 공간을 모두 차지
          overflowY: 'auto', // 내용이 많아지면 내부 스크롤 발생
          padding: '15px 0',
          position: 'relative',
        }}
      >
        {/* Search 탭 내용 */}
        <div style={{ display: activeTab === 'search' ? 'block' : 'none' }}>
          <SearchEquivalence onRun={handleRun} moduleId={moduleId} />
        </div>
        {openTabs.map((tab) => (
          <div
            key={tab.id}
            style={{ display: activeTab === tab.id ? 'block' : 'none', height: '100%' }}
          >
            {/* originalType을 기준으로 렌더링하면 ID 뒤에 숫자가 붙어도 정확히 매칭됩니다. */}
            {tab.originalType === 'ChartPack' && (
              <ChartPack data={data} type={chartType} cols={gridCols} />
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

// --- 기존 스타일 유지 (tabStyle 일부 수정) ---
const tabStyle = (isActive) => ({
  padding: '4px 18px',
  cursor: 'pointer',
  background: isActive ? '#007bff' : '#f8f9fa',
  color: isActive ? '#fff' : '#333',
  border: 'none',
  borderBottom: isActive ? '3px solid #0056b3' : 'none',
  fontSize: '12px',
  fontWeight: 'bold',
  transition: '0.3s',
  marginRight: '5px',
  borderRadius: '5px 5px 0 0',
  lineHeight: '1.2',
});

export default LayoutEquivalence;
