import React, { useState, useCallback, useRef } from 'react';
import TreeList from '../controls/TreeList';
import GridList from '../controls/GridList';

const SaveWorkListPopup = ({ module = 'FAB', onSave, onClose }) => {
  const [folderName, setFolderName] = useState(''); // 폴더명 상태
  const [newGroupName, setNewGroupName] = useState(''); // 새 그룹명 입력 상태
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [groupList, setGroupList] = useState([]);
  const [selectedGroups, setSelectedGroups] = useState([]);
  const [leftWidth, setLeftWidth] = useState(250);

  // --- 좌우 리사이징 로직 ---
  const handleSeparatorMouseDown = useCallback(
    (e) => {
      const startX = e.clientX;
      const startWidth = leftWidth;
      const onMouseMove = (moveEvent) => {
        setLeftWidth(Math.max(150, startWidth + (moveEvent.clientX - startX)));
      };
      const onMouseUp = () => {
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      };
      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    },
    [leftWidth],
  );

  // 그룹 추가 핸들러
  const handleAddGroup = () => {
    if (!newGroupName.trim()) return;
    const newNode = {
      groupkey: `new-${Date.now()}`,
      groupname: newGroupName,
      desc: 'Added by user',
    };
    setGroupList((prev) => [...prev, newNode]);
    setNewGroupName('');
  };

  const handleSelectNode = (data) => {
    setSelectedCategory(data);
    // 더미 데이터 생성 로직 (기존 유지)
    const i = data.id ? 5 : 2;
    let gList = Array.from({ length: i }, (_, k) => ({
      groupkey: String(k),
      groupname: `${data.groupname}-${k}`,
      desc: `Test Sample Group ${k}`,
    }));
    setGroupList(gList);
    setSelectedGroups([]);
  };

  return (
    <div style={popupOverlayStyle}>
      <div style={popupContainerStyle}>
        {/* 헤더 */}
        <div style={popupHeaderStyle}>
          <h4 style={{ margin: 0 }}>Save Work List</h4>
          <button onClick={onClose} style={closeButtonStyle}>
            ✕
          </button>
        </div>

        {/* 메인 콘텐츠 영역 (좌우 여백 20px 추가) */}
        <div style={contentWrapperStyle}>
          {/* 1. 좌측 사이드바 (트리) */}
          <div style={{ ...sideBarStyle, width: `${leftWidth}px` }}>
            <TreeList selectedData={handleSelectNode} />
          </div>

          {/* 2. 리사이저 (여백 사이의 구분선 역할) */}
          <div style={verticalSplitter} onMouseDown={handleSeparatorMouseDown} />

          {/* 3. 우측 입력 및 그리드 영역 */}
          <div style={mainContentStyle}>
            {/* 폴더명 입력 섹션 */}
            <div style={inputSectionStyle}>
              <label style={labelStyle}>Folder Name</label>
              <input
                type="text"
                style={{ ...inputStyle, width: '97%' }}
                value={folderName}
                onChange={(e) => setFolderName(e.target.value)}
                placeholder="Enter folder name..."
              />
            </div>

            {/* 그룹 추가 섹션 */}
            <div style={inputSectionStyle}>
              <label style={labelStyle}>Add Group Name</label>
              <div style={{ display: 'flex', gap: '8px' }}>
                <input
                  type="text"
                  style={{ ...inputStyle, flex: 1 }}
                  value={newGroupName}
                  onChange={(e) => setNewGroupName(e.target.value)}
                  placeholder="New group name..."
                />
                <button style={addButtonStyle} onClick={handleAddGroup}>
                  Add
                </button>
              </div>
            </div>

            <hr style={dividerStyle} />

            {/* 그리드 리스트 섹션 */}
            <div style={sectionStyle}>
              <h5 style={gridTitleStyle}>
                Work List Group {selectedCategory && `- ${selectedCategory.groupname}`}
              </h5>
              <div style={gridContainerStyle}>
                <GridList
                  category="group"
                  selectedValues={selectedGroups}
                  options={groupList}
                  isMulti={false}
                  onSelectChange={(e) => setSelectedGroups(e.target.value)}
                />
              </div>
            </div>
          </div>
        </div>

        {/* 4. 하단 버튼 영역 */}
        <div style={footerStyle}>
          <button style={cancelButtonStyle} onClick={onClose}>
            Cancel
          </button>
          <button style={saveButtonStyle} onClick={() => onSave({ folderName, selectedGroups })}>
            Save
          </button>
        </div>
      </div>
    </div>
  );
};

// --- 추가 및 수정된 스타일 정의 ---

const popupOverlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'rgba(0,0,0,0.5)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  zIndex: 1000,
};

const popupContainerStyle = {
  width: '1000px', // 여백 확보를 위해 너비를 살짝 키움
  height: '65vh', // 높이 조절
  backgroundColor: '#fff',
  borderRadius: '12px',
  display: 'flex',
  flexDirection: 'column',
  overflow: 'hidden',
  boxShadow: '0 10px 30px rgba(0,0,0,0.3)',
};

const popupHeaderStyle = {
  padding: '15px 20px',
  borderBottom: '1px solid #eee',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  backgroundColor: '#f8f9fa',
};

const contentWrapperStyle = {
  display: 'flex',
  flex: 1,
  overflow: 'hidden',
  padding: '0 25px', // [핵심] 전체 좌우 여백 추가
  gap: '10px',
};

const sideBarStyle = {
  height: 'calc(100% - 20px)', // 상하 여백 고려
  marginTop: '20px',
  marginBottom: '20px',
  overflowY: 'auto',
  backgroundColor: '#fcfcfc',
  border: '1px solid #f0f0f0',
};

const verticalSplitter = {
  width: '6px',
  backgroundColor: 'transparent', // 배경은 투명하게
  borderLeft: '1px solid #eee', // 선만 보이게
  cursor: 'col-resize',
  flexShrink: 0,
  margin: '20px 0',
};

const mainContentStyle = {
  flex: 1,
  display: 'flex',
  flexDirection: 'column',
  padding: '20px 10px 20px 20px', // 내부 여백 세밀 조정
  overflowY: 'auto',
};

const inputSectionStyle = { marginBottom: '15px' };

const labelStyle = {
  display: 'block',
  fontSize: '12px',
  fontWeight: 'bold',
  marginBottom: '5px',
  color: '#4a5568',
};

const inputStyle = {
  width: '100%',
  padding: '8px',
  border: '1px solid #cbd5e0',
  borderRadius: '4px',
  fontSize: '14px',
};

const addButtonStyle = {
  padding: '8px 15px',
  backgroundColor: '#4a5568',
  color: '#fff',
  border: 'none',
  borderRadius: '4px',
  cursor: 'pointer',
};

const dividerStyle = { border: '0', borderTop: '1px solid #eee', margin: '10px 0 20px 0' };

const sectionStyle = { flex: 1, display: 'flex', flexDirection: 'column', minHeight: '200px' };

const gridTitleStyle = {
  margin: '0 0 10px 0',
  fontSize: '13px',
  borderBottom: '2px solid #3182ce',
  paddingBottom: '4px',
};

const gridContainerStyle = { flex: 1, border: '1px solid #edf2f7', borderRadius: '4px' };

const footerStyle = {
  padding: '15px 35px', // 푸터 버튼도 콘텐츠 라인에 맞춤
  borderTop: '1px solid #eee',
  display: 'flex',
  justifyContent: 'flex-end',
  gap: '12px',
  backgroundColor: '#fcfcfc',
};

const saveButtonStyle = {
  padding: '8px 24px',
  backgroundColor: '#3182ce',
  color: '#fff',
  border: 'none',
  borderRadius: '4px',
  cursor: 'pointer',
  fontWeight: 'bold',
};

const cancelButtonStyle = {
  padding: '8px 24px',
  backgroundColor: '#fff',
  border: '1px solid #e2e8f0',
  borderRadius: '4px',
  cursor: 'pointer',
};

const closeButtonStyle = {
  background: 'none',
  border: 'none',
  fontSize: '18px',
  cursor: 'pointer',
  color: '#a0aec0',
};

export default SaveWorkListPopup;
