import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { AlertCircle, CheckCircle, Activity, Settings } from 'lucide-react';

const data = [
  { time: '09:00', pass: 98, fail: 2 },
  { time: '10:00', pass: 95, fail: 5 },
  { time: '11:00', pass: 99, fail: 1 },
  { time: '12:00', pass: 88, fail: 12 },
  { time: '13:00', pass: 96, fail: 4 },
];

const QualityDashboard = () => {
  return (
    // 1. 전체 화면 고정 및 스크롤 방지
    <div
      className="bg-gray-50 p-6 overflow-hidden" // 바깥쪽 스크롤 차단
      style={{
        height: 'calc(100vh - 102px)',
      }}
    >
      {/* 2. 헤더: 높이 고정 (flex-none) */}
      <header className="flex justify-between items-center mb-6 flex-none">
        <h1 className="text-2xl font-bold text-gray-800">QC 실시간 모니터링 시스템</h1>
        <div className="flex gap-4">
          <span className="flex items-center gap-2 text-sm text-green-600 font-medium">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span> 시스템 정상
          </span>
          <button className="p-2 bg-white border rounded-md shadow-sm">
            <Settings size={20} />
          </button>
        </div>
      </header>

      {/* 3. 메인 스크롤 영역: flex-1로 남은 공간 모두 차지 */}
      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
        {/* 상단 요약 카드 (상대적으로 고정된 높이) */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8 flex-none">
          <StatCard
            title="금일 목표"
            value="1,200"
            unit="EA"
            icon={<Activity className="text-blue-500" />}
          />
          <StatCard
            title="현재 생산량"
            value="842"
            unit="EA"
            icon={<CheckCircle className="text-green-500" />}
          />
          <StatCard
            title="평균 수율"
            value="96.4"
            unit="%"
            icon={<Activity className="text-purple-500" />}
            color="text-green-600"
          />
          <StatCard
            title="불량 발생"
            value="14"
            unit="건"
            icon={<AlertCircle className="text-red-500" />}
            color="text-red-600"
          />
        </div>

        {/* 하단 차트 및 로그 영역 */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-4">
          {/* 메인 차트 */}
          <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border">
            <h3 className="text-lg font-semibold mb-4">시간별 품질 추이</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={data}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="time" />
                  <YAxis />
                  <Tooltip />
                  <Line
                    type="monotone"
                    dataKey="pass"
                    stroke="#10b981"
                    strokeWidth={3}
                    dot={{ r: 6 }}
                    name="합격률(%)"
                  />
                  <Line
                    type="monotone"
                    dataKey="fail"
                    stroke="#ef4444"
                    strokeWidth={2}
                    name="불량률(%)"
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* 실시간 알림 로그: 내부에서 또 한번 스크롤이 필요할 경우 대비 */}
          <div className="bg-white p-6 rounded-xl shadow-sm border flex flex-col h-[450px] lg:h-auto">
            <h3 className="text-lg font-semibold mb-4 flex-none">최근 품질 이슈</h3>
            <div className="space-y-4 overflow-y-auto flex-1 pr-2">
              <LogItem time="12:04" msg="Line 3: 센서 오차 범위 초과" level="critical" />
              <LogItem time="11:45" msg="Line 1: 원자재 소진 임박" level="warning" />
              <LogItem time="10:30" msg="Line 2: 정기 점검 완료" level="info" />
              {/* 데이터가 많아지면 여기서 스크롤 발생 */}
              {[...Array(10)].map((_, i) => (
                <LogItem key={i} time="09:00" msg={`정상 가동 로그 테스트 ${i}`} level="info" />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// StatCard와 LogItem은 기존과 동일하되, LogItem에 flex-none 등 스타일 미세 조정 가능
const StatCard = ({ title, value, unit, icon, color = 'text-gray-900' }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border flex items-center justify-between">
    <div>
      <p className="text-sm text-gray-500 mb-1">{title}</p>
      <h2 className={`text-2xl font-bold ${color}`}>
        {value}
        <span className="text-sm ml-1 font-normal text-gray-400">{unit}</span>
      </h2>
    </div>
    <div className="p-3 bg-gray-50 rounded-lg">{icon}</div>
  </div>
);

const LogItem = ({ time, msg, level }) => {
  const colors = {
    critical: 'bg-red-100 text-red-700',
    warning: 'bg-yellow-100 text-yellow-700',
    info: 'bg-blue-100 text-blue-700',
  };
  return (
    <div className="flex gap-3 items-start p-3 border-b last:border-0 flex-none">
      <span className="text-xs font-mono text-gray-400 mt-1">{time}</span>
      <p className={`text-sm px-2 py-0.5 rounded ${colors[level]}`}>{msg}</p>
    </div>
  );
};

export default QualityDashboard;
