import React, { useState, useRef } from 'react';

const HeaderMenu = ({ userId, onMenuType, onDataType, onLogout }) => {
  const [activeMenu, setActiveMenu] = useState('Monitoring'); // 메인 메뉴 상태
  const [activeSubMenu, setActiveSubMenu] = useState(null); // 서브 메뉴 상태
  const [hoveredItem, setHoveredItem] = useState(null);
  const [tooltipPos, setTooltipPos] = useState({ left: '50%', transform: 'translateX(-50%)' });
  const containerRefs = useRef({});

  // --- 데이터 정의 ---
  const menuItems = [
    { id: 'Monitoring', label: 'Monitoring' },
    { id: 'Analysis', label: 'Analysis' },
    { id: 'Map', label: 'Map' },
    { id: 'Tools', label: 'Tools' },
    { id: 'MAIN', label: 'Main' },
    { id: 'About', label: 'Information', tip: '시스템 버전 및 릴리즈 정보를 확인합니다.' },
  ];

  const subMenuData = {
    Monitoring: [
      {
        id: 'FAB',
        label: 'FAB',
        tip: [
          '실시간 설비 가동 상태 모니터링',
          'eChart scatter/box 지원',
          '실시간 설비 가동 상태 및 알람을 데이터를 취합하여(DB 데이터) 모니터링합니다.',
          '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
          'Line ~ Y2Item 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
          'Engine은 현재 eChart만 지원합니다.',
          'Type은 차트 종류로 scatter, scatter-data, scatter-priority, boxplot 지원합니다.',
          'cols는 차트 열배치 숫자입니다.',
          'Add, Remove, Save는 현재 지원 안합니다.',
          'Run 버튼 클릭 Chart와 Output이 생성됩니다. -> 데이터는 Random 생성됩니다.',
          '차트는 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
        ],
      },
      { id: 'ET', label: 'ET', tip: ['ET 데이터 실시간 모니터링'] },
      { id: 'EDS', label: 'EDS', tip: ['EDS 공정 데이터 모니터링'] },
    ],
    Analysis: [
      { id: 'Equivalence', label: 'Equivalence', tip: ['설비 간 동일성 분석'] },
      { id: 'Sleuth', label: 'Sleuth', tip: ['데이터 추적 및 분석'] },
      { id: 'XYCorrelation', label: 'XY Correlation', tip: ['상관관계 분석'] },
    ],
    Map: [
      {
        id: 'EDSMAP',
        label: 'EDS Map',
        tip: [
          '웨이퍼의 공간적 데이터 분포를 시각적으로 확인합니다.',
          '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
          'Wafer Geometry는 Wafer Die(Chip) 생성 조건입니다. DieSize 조정시 각기 다른 Die(Chip)가 생성됩니다.',
          'Line ~ LOT.WAFER 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
          'columns는 Wafer Map의 열배치 숫자입니다.',
          'Map Type은 Map 종류로 EDS(bin), MEASURE, DEFECT, METRO-CD Map을 지원합니다.',
          'Draw Wafer Maps 버튼 클릭 Wafer Map Gallery로 생성됩니다. -> 데이터는 Random 생성됩니다.',
          'Map은 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
          'Map은 확대모드에서 Zoom Box 기능 지원합니다.',
        ],
      },
      {
        id: 'DEFECTMAP',
        label: 'Defect Map',
        tip: [
          '결함 위치 시각화 맵',
          '대량 계측 데이터 기반의 Critical Dimension을 분석합니다.',
          '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
          'Wafer Geometry는 Wafer Die(Chip) 생성 조건입니다. DieSize 조정시 각기 다른 Die(Chip)가 생성됩니다.',
          'Line ~ LOT.WAFER 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
          'Poly Order는 X,Y radius Gradient Chart의 Polynomial Trend의 차수를 조정합니다. -> 차수에 따라 Trend Line 변경됩니다.',
          'Point Size는 gradient Map or Chart의 Point Size를 설정합니다.',
          'Point Style은 Map, Chart의 Point Style을 설정합니다.',
          'View는 Map, X Gradient Chart, Y Gradient Chart Row 세트의 표시 기준을 설정합니다.',
          'Draw Wafer Maps And Gradient Chart 버튼 클릭시 view 선택 기준의 Map, X Gradient Chart, Y Gradient Chart Row 세트가 열 배치로 생성됩니다. -> 데이터는 Random 생성됩니다.',
          'Map, 차트 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
        ],
      },
      {
        id: 'METROMAP',
        label: 'Metro Map',
        tip: [
          '계측 CD 시각화 맵',
          '대량 계측 데이터 기반의 Critical Dimension을 분석합니다.',
          '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
          'Wafer Geometry는 Wafer Die(Chip) 생성 조건입니다. DieSize 조정시 각기 다른 Die(Chip)가 생성됩니다.',
          'Line ~ LOT.WAFER 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
          'Poly Order는 X,Y radius Gradient Chart의 Polynomial Trend의 차수를 조정합니다. -> 차수에 따라 Trend Line 변경됩니다.',
          'Point Size는 gradient Map or Chart의 Point Size를 설정합니다.',
          'Point Style은 Map, Chart의 Point Style을 설정합니다.',
          'View는 Map, X Gradient Chart, Y Gradient Chart Row 세트의 표시 기준을 설정합니다.',
          'Draw Wafer Maps And Gradient Chart 버튼 클릭시 view 선택 기준의 Map, X Gradient Chart, Y Gradient Chart Row 세트가 열 배치로 생성됩니다. -> 데이터는 Random 생성됩니다.',
          'Map, 차트 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
        ],
      },
      {
        id: 'MASSIVEMAP',
        label: 'Massive Metrology CD',
        tip: [
          '대량 계측 데이터 기반의 Critical Dimension을 분석합니다.',
          '버튼 클릭시마다 메뉴가 탭으로 생성됩니다. -> 각기 다른 조건 실행 가능합니다.',
          'Wafer Geometry는 Wafer Die(Chip) 생성 조건입니다. DieSize 조정시 각기 다른 Die(Chip)가 생성됩니다.',
          'Line ~ LOT.WAFER 까지 조건 조회 후 조건 선택합니다. -> 데이터는 고정되이 있고 filter는 지원합니다.',
          'Poly Order는 X,Y radius Gradient Chart의 Polynomial Trend의 차수를 조정합니다. -> 차수에 따라 Trend Line 변경됩니다.',
          'Point Size는 gradient Map or Chart의 Point Size를 설정합니다.',
          'Point Style은 Map, Chart의 Point Style을 설정합니다.',
          'View는 Map, X Gradient Chart, Y Gradient Chart Row 세트의 표시 기준을 설정합니다.',
          'Draw Wafer Maps And Gradient Chart 버튼 클릭시 view 선택 기준의 Map, X Gradient Chart, Y Gradient Chart Row 세트가 열 배치로 생성됩니다. -> 데이터는 Random 생성됩니다.',
          'Map, 차트 더블클릭시 확대모드 및 Gallery모드 변경 됩니다.',
        ],
      },
    ],
    Tools: [{ id: 'PHOTOMAP', label: 'Photo Map Generator', tip: ['포토 공정 맵 생성 툴'] }],
  };

  // --- 핸들러 ---
  const handleMenuClick = (menuId, label) => {
    setActiveMenu(menuId);
    setActiveSubMenu(null); // 메인 메뉴 바뀔 때 서브메뉴 선택 초기화
    if ((menuId === 'Copyrights' || menuId === 'About' || menuId === 'MAIN') && onMenuType)
      onMenuType(menuId, label);
  };

  const handleSubMenuClick = (subItem) => {
    setActiveSubMenu(subItem.id);
    if (onMenuType) onMenuType(subItem.id, subItem.label);
  };

  const handleMouseEnter = (id) => {
    setHoveredItem(id);
    const element = containerRefs.current[id];
    if (element) {
      const rect = element.getBoundingClientRect();
      const viewportWidth = window.innerWidth;
      const tooltipWidth = 300;
      if (rect.left + tooltipWidth / 2 > viewportWidth)
        setTooltipPos({ left: 'auto', right: '0', transform: 'none' });
      else if (rect.left - tooltipWidth / 2 < 0)
        setTooltipPos({ left: '0', right: 'auto', transform: 'none' });
      else setTooltipPos({ left: '50%', right: 'auto', transform: 'translateX(-50%)' });
    }
  };

  return (
    <div style={wrapperStyle}>
      {/* 1. 메인 헤더 (Header) */}
      <header style={headerStyle}>
        <div style={logoStyle}>
          <span style={logoIconStyle}>📊</span>
          <span style={logoTextStyle}>DEVICE SOLUTION</span>
        </div>

        <nav style={navStyle}>
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleMenuClick(item.id, item.label)}
              style={{
                ...menuButtonStyle,
                ...(activeMenu === item.id ? activeMenuStyle : {}),
              }}
            >
              {item.label}
            </button>
          ))}
          <span style={infoTextStyle}>
            F11를 누르면 전체화면 모드로 Winform UI 처럼 동작 합니다.
          </span>
        </nav>

        <div style={rightSectionStyle}>
          <div style={userStatusStyle}>
            <span style={userIconStyle}>👤</span>
            <span style={userIdStyle}>{userId || 'Guest'}</span>
          </div>

          <button style={logoutButtonStyle} onClick={onLogout} title="로그아웃">
            Logout
          </button>

          <button
            style={copyrightButtonStyle}
            onClick={() => onMenuType?.('Copyrights', 'Copyrights')}
          >
            © Copyrights
          </button>
          <div style={selectWrapperStyle}>
            <span style={selectLabelStyle}>Source</span>
            <select onChange={(e) => onDataType(e.target.value)} style={selectStyle}>
              <option value="Gen">Simulation</option>
              <option value="Api">Live DB</option>
            </select>
          </div>
        </div>
      </header>

      {/* 2. 서브 헤더 (Sub-header) - 상하좌우 여백 및 높이 통일 */}
      <div style={subHeaderStyle}>
        <div style={subContainerStyle}>
          {subMenuData[activeMenu]?.map((subItem) => (
            <div
              key={subItem.id}
              ref={(el) => (containerRefs.current[subItem.id] = el)}
              style={{ position: 'relative', display: 'flex', alignItems: 'center' }}
              onMouseEnter={() => handleMouseEnter(subItem.id)}
              onMouseLeave={() => setHoveredItem(null)}
            >
              <button
                onClick={() => handleSubMenuClick(subItem)}
                style={{
                  ...subItemButtonStyle,
                  ...(activeSubMenu === subItem.id ? activeSubMenuStyle : {}),
                }}
              >
                {subItem.label}
              </button>

              {hoveredItem === subItem.id && (
                <div style={{ ...tooltipStyle, ...tooltipPos }}>
                  {Array.isArray(subItem.tip)
                    ? subItem.tip.map((line, i) => (
                        <div key={i} style={{ marginBottom: '4px' }}>
                          • {line}
                        </div>
                      ))
                    : subItem.tip}
                  <div style={tooltipArrowStyle} />
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const userStatusStyle = {
  display: 'flex',
  alignItems: 'center',
  marginRight: '12px',
  padding: '0 8px',
  borderRight: '1px solid #4a5568',
};

const userIconStyle = {
  fontSize: '12px',
  marginRight: '6px',
  color: '#63b3ed',
};

const userIdStyle = {
  fontSize: '11px',
  color: '#e2e8f0',
  fontWeight: '600',
};

const logoutButtonStyle = {
  background: '#e53e3e',
  color: '#fff',
  border: 'none',
  fontSize: '10px',
  padding: '2px 8px',
  borderRadius: '4px',
  cursor: 'pointer',
  marginRight: '10px',
  fontWeight: 'bold',
  transition: 'background 0.2s',
};

// --- 스타일 정의 수정 ---

const wrapperStyle = {
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
};

// 공통 여백 변수
const COMMON_PADDING = '0 16px';
const COMMON_HEIGHT = '32px';

const headerStyle = {
  height: COMMON_HEIGHT,
  padding: COMMON_PADDING,
  background: '#1a202c',
  color: '#e2e8f0',
  display: 'flex',
  alignItems: 'center',
  borderBottom: '1px solid #2d3748',
  boxSizing: 'border-box',
};

const subHeaderStyle = {
  height: COMMON_HEIGHT, // Header와 동일한 높이
  padding: COMMON_PADDING, // Header와 동일한 좌우 여백
  background: '#2d3748',
  display: 'flex',
  alignItems: 'center',
  borderBottom: '1px solid #1a202c', // 구분선 추가
  boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
  boxSizing: 'border-box',
};

const subContainerStyle = {
  display: 'flex',
  gap: '6px', // 버튼 간격 소폭 조정
  alignItems: 'center',
  height: '100%',
};

const menuButtonStyle = {
  height: '24px', // 버튼 높이 명시
  padding: '0 12px',
  background: 'transparent',
  border: 'none',
  color: '#a0aec0',
  fontSize: '11px',
  fontWeight: '600',
  cursor: 'pointer',
  borderRadius: '4px',
  display: 'flex',
  alignItems: 'center',
};

const subItemButtonStyle = {
  height: '24px', // 버튼 높이를 조금 더 명확하게 설정
  padding: '0 10px', // 상하 0, 좌우 16px로 넉넉하게 설정
  background: 'rgba(255, 255, 255, 0.05)',
  border: '1px solid #4a5568',
  borderRadius: '4px', // 약간 더 부드러운 곡선
  color: '#cbd5e0',
  fontSize: '10.5px',
  fontWeight: '500', // 가독성을 위해 두께 약간 추가
  cursor: 'pointer',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center', // 텍스트 중앙 정렬
  transition: 'all 0.2s ease', // 부드러운 상태 변화
  whiteSpace: 'nowrap', // 텍스트 줄바꿈 방지
};

const infoTextStyle = {
  fontSize: '12px',
  color: '#718096',
  marginLeft: '4px',
  display: 'flex',
  alignItems: 'center',
};
// --- 스타일 정의 ---

const logoStyle = { display: 'flex', alignItems: 'center', gap: '8px', marginRight: '24px' };
const logoTextStyle = {
  fontSize: '11px',
  fontWeight: '800',
  color: '#63b3ed',
  letterSpacing: '0.5px',
};
const logoIconStyle = { fontSize: '12px' };

const navStyle = { display: 'flex', gap: '4px', flex: 1 };

const activeMenuStyle = {
  color: '#fff',
  background: 'rgba(255,255,255,0.1)',
};

const activeSubMenuStyle = {
  background: '#3182ce',
  color: '#fff',
};

const rightSectionStyle = { display: 'flex', alignItems: 'center' };
const copyrightButtonStyle = {
  background: 'none',
  border: '1px solid #4a5568',
  color: '#718096',
  fontSize: '10px',
  padding: '2px 8px',
  borderRadius: '4px',
  cursor: 'pointer',
  marginRight: '10px',
};
const selectWrapperStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '5px',
  background: '#1a202c',
  padding: '1px 6px',
  borderRadius: '4px',
  border: '1px solid #4a5568',
};
const selectLabelStyle = { fontSize: '9px', color: '#4a5568', fontWeight: 'bold' };
const selectStyle = {
  background: 'transparent',
  color: '#fff',
  border: 'none',
  fontSize: '10px',
  outline: 'none',
};

const tooltipStyle = {
  position: 'absolute',
  top: '38px',
  backgroundColor: 'rgba(33, 37, 41, 0.98)',
  color: '#fff',
  padding: '10px 14px',
  borderRadius: '6px',
  fontSize: '11px',
  zIndex: 1000,
  boxShadow: '0 8px 16px rgba(0,0,0,0.4)',
  pointerEvents: 'none',
  border: '1px solid #495057',
  width: 'max-content',
  maxWidth: '380px', // 너무 길어지지 않게 제한
  whiteSpace: 'normal', // 줄바꿈 허용
  wordBreak: 'keep-all', // 단어 단위 줄바꿈
  lineHeight: '1.5',
};

const tooltipArrowStyle = {
  position: 'absolute',
  bottom: '100%',
  left: '50%',
  transform: 'translateX(-50%)',
  borderWidth: '6px',
  borderStyle: 'solid',
  borderColor: 'transparent transparent rgba(33, 37, 41, 0.98) transparent',
};
export default HeaderMenu;
