import ReactECharts from 'echarts-for-react';
import { useMemo } from 'react';

// 1. Reference 기반 동일성 위반 탐지 로직 (수정 사항 없음)
const findOutliersByRef = (data, refData, pValueThreshold = 2.58) => {
  if (!data.length || !refData.length) return { outlierResults: [], refMean: 0 };

  const refValues = refData.map((d) => d.value);
  const refMean = refValues.reduce((a, b) => a + b, 0) / refValues.length;
  const refSD = Math.sqrt(
    refValues.map((x) => Math.pow(x - refMean, 2)).reduce((a, b) => a + b, 0) / refValues.length,
  );

  const equips = [...new Set(data.map((d) => d.equip))];
  const outlierResults = [];

  equips.forEach((eq) => {
    const groupVals = data.filter((d) => d.equip === eq).map((d) => d.value);
    const groupMean = groupVals.reduce((a, b) => a + b, 0) / groupVals.length;

    const standardError = refSD / Math.sqrt(groupVals.length);
    const zScore = (groupMean - refMean) / (standardError || 1);

    outlierResults.push({
      equip: eq,
      zScore: parseFloat(zScore.toFixed(3)),
      isOutlier: Math.abs(zScore) > pValueThreshold,
    });
  });

  return { outlierResults, refMean };
};

const EquivalenceChart = ({ data, title = 'Reference-based' }) => {
  const { referenceData, testData } = useMemo(() => {
    // 초기값 설정: 한 번의 순회로 두 배열을 동시에 생성
    const initialAcc = { referenceData: [], testData: [] };

    const processed = data.reduce((acc, item, idx) => {
      // 공통 데이터 포맷팅 함수 (코드 중복 방지)
      const formattedItem = {
        equip: item.equip,
        value: item.value,
        // 가급적 item 내부의 고유 ID를 사용하세요.
        // 예: id: item.id || `${item.equip}-${idx}`
        id: `${item.equip}-${idx}`,
      };

      if (item.equip === '0REF-STD') {
        acc.referenceData.push(formattedItem);
      } else {
        acc.testData.push(formattedItem);
      }

      return acc;
    }, initialAcc);

    return processed;
  }, [data]);

  const { outlierResults, refMean } = useMemo(
    () => findOutliersByRef(testData, referenceData),
    [testData, referenceData],
  );

  const getOption = useMemo(() => {
    const allGroups = ['0REF-STD', ...new Set(testData.map((d) => d.equip))];
    const boxData = [];
    const scatterData = [];
    const meanPoints = [];

    allGroups.forEach((groupName, idx) => {
      const isRef = groupName === '0REF-STD';
      const group = isRef ? referenceData : testData.filter((d) => d.equip === groupName);
      const vals = group.map((d) => d.value).sort((a, b) => a - b);

      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
      const stats = [
        vals[0],
        vals[Math.floor(vals.length * 0.25)],
        vals[Math.floor(vals.length * 0.5)],
        vals[Math.floor(vals.length * 0.75)],
        vals[vals.length - 1],
      ];

      const res = outlierResults.find((r) => r.equip === groupName);
      const isOutlier = res?.isOutlier || false;
      const zScore = isRef ? 0 : (res?.zScore ?? 'N/A');

      let color = 'rgba(200, 200, 200, 0.3)';
      let borderColor = '#999';

      if (isRef) {
        color = 'rgba(47, 69, 84, 0.3)';
        borderColor = '#172833';
      } else if (isOutlier) {
        color = 'rgba(255, 99, 132, 0.3)';
        borderColor = '#ff6384';
      }

      // [수정] boxData에 zScore를 명확히 포함
      boxData.push({
        value: stats,
        zScore: zScore,
        itemStyle: { color, borderColor, borderWidth: isOutlier || isRef ? 2 : 1 },
      });

      group.forEach((d) => {
        const jitter = Math.random() * 0.1 - 0.05;
        scatterData.push({ value: [parseFloat((idx + jitter).toFixed(3)), d.value] });
      });
      meanPoints.push([idx, mean.toFixed(3)]);
    });

    return {
      title: {
        text: `${title} Equivalence`,
        subtext: `Target: REF-STD(mean=${refMean.toFixed(2)}) | Outliers: ${
          outlierResults
            .filter((r) => r.isOutlier)
            .map((r) => r.equip)
            .join(', ') || 'None'
        }`,
        left: 'center',
        top: 5, // 상단 여백 최소화
        // 메인 타이틀 스타일
        textStyle: {
          fontSize: 13, // 타이틀 크기 축소 (기본 18)
          fontWeight: 'bold',
          overflow: 'break', // 길어지면 줄바꿈
        },
        // 서브타이틀 스타일
        subtextStyle: {
          fontSize: 10, // 서브타이틀 크기 축소 (기본 12)
          color: '#666',
          overflow: 'break',
        },
        itemGap: 2, // 타이틀과 서브타이틀 사이의 간격 축소
      },
      tooltip: {
        trigger: 'item',
        formatter: (params) => {
          if (params.seriesName === 'Distribution') {
            const v = params.data.value; // [index, min, q1, median, q3, max]
            const z = params.data.zScore; // 수정: item에 포함시킨 zScore 참조
            const equipName = allGroups[v[0]];
            const isRef = equipName === '0REF-STD';

            return `
              <div style="font-weight:bold; border-bottom:1px solid #ccc; margin-bottom:5px;">${equipName}</div>
              ${
                !isRef
                  ? `<div style="color:${Math.abs(z) > 2.58 ? '#ff6384' : '#333'}">
                <b>z-Score: ${z}</b>
              </div>`
                  : '<div><b>Reference Standard</b></div>'
              }
              <span style="color:${params.color}">●</span> Max: ${v[5]}<br/>
              <span style="color:${params.color}">●</span> Q3: ${v[4]}<br/>
              <span style="color:${params.color}">●</span> Median: ${v[3]}<br/>
              <span style="color:${params.color}">●</span> Q1: ${v[2]}<br/>
              <span style="color:${params.color}">●</span> Min: ${v[1]}
            `;
          }
          if (params.seriesName === 'Raw Data') {
            return `<b>Raw Value:</b> ${params.data.value[1]}`;
          }
          return '';
        },
      },
      legend: { data: ['Distribution', 'Raw Data', 'Mean Trend'], bottom: 15 },
      xAxis: {
        type: 'value',
        min: -1,
        max: allGroups.length,
        interval: 1,
        axisLabel: { formatter: (val) => allGroups[Math.round(val)] || '' },
      },
      yAxis: {
        type: 'value',
        scale: true,
        splitLine: { lineStyle: { type: 'dashed' } },
        axisLine: false,
      },
      series: [
        {
          name: 'Distribution',
          type: 'boxplot',
          data: boxData.map((item, i) => ({
            value: [i, ...item.value],
            zScore: item.zScore, // [핵심] 여기에 zScore를 넘겨줘야 tooltip에서 params.data.zScore로 접근 가능
            itemStyle: item.itemStyle,
          })),
        },
        {
          name: 'Raw Data',
          type: 'scatter',
          symbolSize: 6,
          itemStyle: { color: '#463939', opacity: 0.4 },
          data: scatterData,
        },
        {
          name: 'Mean Trend',
          type: 'line',
          lineStyle: { type: 'dashed', color: '#ee6666' },
          itemStyle: { color: '#ee6666' },
          data: meanPoints,
          markLine: {
            data: [
              { yAxis: refMean, label: { formatter: 'Ref Mean' }, lineStyle: { type: 'solid' } },
            ],
            lineStyle: { color: '#2f4554', width: 2 },
          },
        },
      ],
    };
  }, [testData, referenceData, outlierResults, refMean]);

  return <ReactECharts option={getOption} style={{ height: '100%', width: '100%' }} />;
};

export default EquivalenceChart;
