import React, { useState } from 'react';

const LoginPage = ({ onLoginSuccess }) => {
  const [formData, setFormData] = useState({ empId: '', password: '' });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);
    
    // 시뮬레이션: 1.5초 후 로그인 성공 처리
    setTimeout(() => {
      setLoading(false);
      if (onLoginSuccess) {
        onLoginSuccess({ empId: formData.empId, empName: '황승태' });
      }
    }, 1500);
  };

  return (
    <div className="relative min-h-screen flex items-center justify-center bg-[#020617] overflow-hidden">
      
      {/* --- 배경 애니메이션 요소 (반도체 회로 느낌) --- */}
      <div className="absolute inset-0 z-0">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-blue-900/20 rounded-full blur-[120px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-900/20 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: '2s' }}></div>
      </div>

      {/* --- 로그인 카드 (Glassmorphism 적용) --- */}
      <div className="relative z-10 w-full max-w-[420px] p-1 bg-gradient-to-br from-blue-500/20 to-transparent rounded-[2rem]">
        <div className="bg-[#0f172a]/80 backdrop-blur-xl p-10 rounded-[1.9rem] shadow-2xl border border-white/10">
          
          {/* 로고 영역 */}
          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-16 h-16 bg-blue-600 rounded-2xl mb-4 shadow-lg shadow-blue-500/30">
              <span className="text-3xl">📊</span>
            </div>
            <h1 className="text-3xl font-black text-white tracking-tighter italic">
              FOR <span className="text-blue-500">LINK</span> SYSTEM
            </h1>
            <p className="text-slate-400 text-sm mt-3 font-light tracking-widest uppercase">
              MES Quality Solution
            </p>
            <p className="text-slate-400 text-sm mt-3 font-light tracking-widest uppercase">
              아무거나 입력해도 로그인 됩니다.
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* 사번 입력 */}
            <div className="group">
              <label className="block text-xs font-bold text-slate-400 mb-1.5 ml-1 uppercase tracking-wider">Employee ID</label>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500">👤</span>
                <input
                  type="text"
                  name="empId"
                  required
                  className="w-full pl-11 pr-4 py-3.5 bg-slate-800/50 border border-slate-700 rounded-xl text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 transition-all"
                  placeholder="사번을 입력하세요"
                  onChange={handleChange}
                />
              </div>
            </div>

            {/* 비밀번호 입력 */}
            <div className="group">
              <label className="block text-xs font-bold text-slate-400 mb-1.5 ml-1 uppercase tracking-wider">Password</label>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500">🔑</span>
                <input
                  type="password"
                  name="password"
                  required
                  className="w-full pl-11 pr-4 py-3.5 bg-slate-800/50 border border-slate-700 rounded-xl text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 transition-all"
                  placeholder="••••••••"
                  onChange={handleChange}
                />
              </div>
            </div>

            {/* 체크박스 및 링크 */}
            <div className="flex items-center justify-between px-1">
              <label className="flex items-center text-xs text-slate-400 cursor-pointer group">
                <input type="checkbox" className="hidden" />
                <div className="w-4 h-4 border border-slate-600 rounded mr-2 group-hover:border-blue-500 transition-all flex items-center justify-center">
                  <div className="w-2 h-2 bg-blue-500 rounded-sm opacity-0 group-hover:opacity-50"></div>
                </div>
                자동 로그인
              </label>
              <button type="button" className="text-xs text-blue-400 hover:text-blue-300 transition-colors">계정 활성화 문의</button>
            </div>

            {/* 로그인 버튼 */}
            <button
              type="submit"
              disabled={loading}
              className="relative w-full overflow-hidden group py-4 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-xl transition-all shadow-xl shadow-blue-900/20 active:scale-[0.98]"
            >
              {loading ? (
                <div className="flex items-center justify-center gap-2">
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  <span>인증 중...</span>
                </div>
              ) : (
                <span className="flex items-center justify-center">
                  ENTER SYSTEM <span className="ml-2 group-hover:translate-x-1 transition-transform">→</span>
                </span>
              )}
            </button>
          </form>

          {/* 푸터 영역 */}
          <div className="mt-10 text-center">
            <p className="text-[10px] text-slate-500 font-medium tracking-[0.2em] uppercase">
              Security Level: High Access Only
            </p>
            <p className="text-[10px] text-slate-600 mt-2">
              © 2026 FOR LINK SYSTEM. Ver 2.4.0
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;